modules[S(276)] = function()
local Players = game:GetService(S(360))
local Workspace = game:GetService(S(293))
local function getCurrentPlot()
    local player = Players.LocalPlayer
    local mineWorld = Workspace:FindFirstChild(S(56))
    local plots = mineWorld and mineWorld:FindFirstChild(S(228))
    if not plots then
        return nil
    end
    for _, plot in ipairs(plots:GetChildren()) do
        if plot:GetAttribute(S(217)) == player.UserId then
            return plot
        end
    end
    return nil
end
return getCurrentPlot
end
